#include <bits/stdc++.h>
using namespace std;
const int MAXN=2000005;
int total_edges, next_edge[MAXN], head[MAXN], to[MAXN], cap[MAXN], dist_arr[MAXN], source, sink, nodes, edges, x_arr[MAXN], y_arr[MAXN], visited_flag[MAXN], weight[MAXN], flow_curr[MAXN], k_value, c_value, d_value;
queue<int> q;
void addEdge(int u, int v, int capacity, int weightVal){
    next_edge[++total_edges]=head[u];
    head[u]=total_edges;
    to[total_edges]=v;
    cap[total_edges]=capacity;
    weight[total_edges]=weightVal;
    next_edge[++total_edges]=head[v];
    head[v]=total_edges;
    to[total_edges]=u;
    cap[total_edges]=0;
    weight[total_edges]=-weightVal;
}
int spfa(){
    q.push(source);
    memset(dist_arr,0x3f,sizeof dist_arr);
    dist_arr[source]=0;
    while (!q.empty()){
        int u=q.front();q.pop();visited_flag[u]=0;
        for (int i=head[u];i;i=next_edge[i])
            if (cap[i]&&dist_arr[to[i]]>dist_arr[u]+weight[i]){
                dist_arr[to[i]]=dist_arr[u]+weight[i];
                if (!visited_flag[to[i]]){
                    visited_flag[to[i]]=1;
                    q.push(to[i]);
                }
            }
    }
    return dist_arr[sink]<=1e9;
}
int dfs(int u,int flow_in){
    int total_flow=0,flow_bottle;
    visited_flag[u]=1;
    if (u==sink)return flow_in;
    for (int &i=flow_curr[u];i;i=next_edge[i])
        if (!visited_flag[to[i]]&&cap[i]&&dist_arr[to[i]]==dist_arr[u]+weight[i]&&(flow_bottle=min(flow_in,dfs(to[i],min(flow_in,cap[i]))))){
            cap[i]-=flow_bottle;
            cap[i^1]+=flow_bottle;
            total_flow+=flow_bottle;flow_in-=flow_bottle;
            if (!flow_in)return total_flow;
        }
    return total_flow;	
}
int main(){
    scanf("%d%d%d%d%d",&nodes,&edges,&k_value,&c_value,&d_value);
    source=0; sink=1;
    total_edges=1;
    for (int i=1;i<=k_value;i++){
        int x;
        scanf("%d",&x);
        addEdge(source,x+1,1,0);
    }
    for (int i=1;i<=edges;i++)scanf("%d%d",&x_arr[i],&y_arr[i]);
    for (int i=0;i<=nodes+k_value;i++){
        addEdge(2+i*nodes,sink,k_value,0);
        if (i==nodes+k_value)break;
        for (int j=1;j<=edges;j++)
            for (int l=k_value;l>=0;l--) {
                addEdge(x_arr[j]+1+i*nodes,y_arr[j]+1+i*nodes+n,1,(l*2+1)*d_value+c_value);
                addEdge(y_arr[j]+1+i*nodes,nodes+x_arr[j]+1+i*nodes,1,(l*2+1)*d_value+c_value);
            }
        for (int j=1;j<=nodes;j++)addEdge(j+1+i*nodes,j+1+i*nodes+n,k_value,c_value);
    }
    printf("%d\n",gao());
}
